 64px;\n    font-size: 22px;\n  }\n  .day-pill {\n    width: 48px;\n    padding: 9px 0;\n  }\n  .class-card {\n    padding: 13px;\n    gap: 10px;\n  }\n  .menu-item {\n    padding: 15px 16px;\n    gap: 12px;\n  }\n}\n\n/* ===== Mobile bottom nav (floating pill) ===== */\n.mobile-tabbar {\n  display: none;\n}\n@media (max-width: 880px) {\n  .mobile-tabbar {\n    display: flex;\n    position: fixed;\n    left: 50%;\n    bottom: 16px;\n    transform: translateX(-50%);\n    z-index: 60;\n    align-items: center;\n    gap: 6px;\n    width: calc(100% - 24px);\n    max-width: 460px;\n    padding: 12px 16px;\n    border-radius: 26px;\n    background: rgba(17,17,16,0.92);\n    backdrop-filter: blur(16px);\n    -webkit-backdrop-filter: blur(16px);\n    border: 1px solid var(--line);\n    box-shadow: 0 14px 34px rgba(0,0,0,0.5);\n  }\n  .mt-item {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n    padding: 8px 4px;\n    border-radius: 16px;\n    color: var(--gray);\n    cursor: pointer;\n    position: relative;\n    transition: color .15s ease, background .15s ease;\n  }\n  .mt-item svg { width: 22px; height: 22px; stroke-width: 1.8; }\n  .mt-item span { font-size: 11px; font-weight: 600; }\n  .mt-item.active {\n    color: var(--white);\n    background: var(--charcoal-2);\n  }\n  .mt-item.active::before {\n    content: '';\n    position: absolute;\n    top: 3px;\n    width: 4px;\n    height: 4px;\n    border-radius: 50%;\n    background: var(--gold);\n  }\n  .mt-center {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    width: 50px;\n    height: 50px;\n    flex-shrink: 0;\n    border-radius: 15px;\n    background: linear-gradient(160deg, var(--charcoal-2), var(--black));\n    border: 1px solid var(--line);\n    color: var(--white);\n    cursor: pointer;\n  }\n  .mt-center svg { width: 22px; height: 22px; }\n  .mt-center.open svg { color: var(--gold-light); }\n\n  .mt-more-panel {\n    disp